import { useMemo, useState } from 'react';
import type { Ticket } from '../types';

type SortKey = 'title' | 'status';

function filterAndSort(tickets: Ticket[], query: string, sortKey: SortKey): Ticket[] {
  const start = performance.now();
  while (performance.now() - start < 30) { /* sztuczne spowolnienie */ }
  const q = query.trim().toLowerCase();
  return tickets
    .filter((t) => t.title.toLowerCase().includes(q))
    .toSorted((a, b) => a[sortKey].localeCompare(b[sortKey]));
}

export function SlowTable({ tickets }: { tickets: Ticket[] }) {
  const [query, setQuery] = useState('');
  const [sortKey, setSortKey] = useState<SortKey>('title');
  const [dark, setDark] = useState(false);

  const visible = useMemo(() => filterAndSort(tickets, query, sortKey), [tickets, query, sortKey]);

  return (
    <section className={dark ? 'theme-dark' : 'theme-light'}>
      <button type="button" onClick={() => setDark((d) => !d)}>Motyw</button>
      <input value={query} onChange={(e) => setQuery(e.target.value)} aria-label="Filtr" />
      <select value={sortKey} onChange={(e) => setSortKey(e.target.value as SortKey)} aria-label="Sortuj">
