// Sparkline.jsx
import { memo, useEffect, useState } from 'react';

function arePropsEqual(prev, next) {
  return (
    prev.color === next.color &&
    prev.points.length === next.points.length &&
    prev.points.every((p, i) => p === next.points[i])
  );
}

export const Sparkline = memo(function Sparkline({ points, color }) {
  console.log('render Sparkline', points.length);
  const max = Math.max(...points, 1);
  const path = points.map((p, i) => `${i * 10},${30 - (p / max) * 30}`).join(' ');
  return (
    <svg width={points.length * 10} height={30} role="img" aria-label={`Wykres ${points.length} punktów`}>
      <polyline points={path} fill="none" stroke={color} />
    </svg>
  );
}, arePropsEqual);

export function LiveSparkline() {
  const [points, setPoints] = useState([3, 5, 2, 8]);

  useEffect(() => {
    let tick = 0;
    const id = setInterval(() => {
      tick += 1;
      setPoints((p) => (tick % 5 === 0 ? [...p, Math.round(Math.random() * 10)] : [...p]));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  return <Sparkline points={points} color="teal" />;
}

